/**
 * next_prime_number - return the next prime number
 * @x: the starting point for searching to test
 *
 * A prime number is an integer greater than 1 that is only divisible by
 * itself and 1.  The set of prime numbers is computed using the Sieve of
 * Eratoshenes (on finding a prime, all multiples of that prime are removed
 * from the set) enabling a fast lookup of the next prime number larger than
 * @x. If the sieve fails (memory limitation), the search falls back to using
 * slow trial-divison, up to the value of ULONG_MAX (which is reported as the
 * final prime as a sentinel).
 *
 * Returns: the next prime number larger than @x
 */

/* 학습 해설
 * 공개 다음 소수 조회·last 경계와 RCU 재진입
 * 캐시 범위 확장이 필요한 조회에서 읽기 구간을 나갔다가 다시 들어가는 제어 흐름을 배웁니다.
 * next_prime_number는 RCU 읽기 보호를 얻고 현재 캐시를 읽습니다. x>=p->last이면 읽기 보호를 풀고 확장을 시도합니다. 성공 후 다시 보호를 얻어 현재 포인터를 읽고 조건을 반복합니다. 정상 조회는 x+1부터 p->last를 경계로 find_next_bit합니다. find_next_bit의 경계까지 못 찾은 반환값도 마지막 소수 last와 일치하는 문맥입니다.
 * x61,초기 last61이면 확장이 필요하고,x60이면61을 돌려주는 흐름을 추적합니다. 보호 밖에서 오래된 p를 계속 쓰지 않고 재진입 후 포인터를 갱신하는 이유를 설명합니다.
 */
unsigned long next_prime_number(unsigned long x)
{
	const struct primes *p;

	rcu_read_lock();
	p = rcu_dereference(primes);
	while (x >= p->last) {
		rcu_read_unlock();

		if (!expand_to_next_prime(x))
			return slow_next_prime_number(x);

		rcu_read_lock();
		p = rcu_dereference(primes);
	}
	x = find_next_bit(p->primes, p->last, x + 1);
	rcu_read_unlock();

	return x;
}
EXPORT_SYMBOL(next_prime_number);

